C(12, 1, "Cinco adultos que invierten", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Cuántos adultos invierten en tu hijo, además de ti?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] En Cómo criar jóvenes de fe sólida, Kara Powell y Chap Clark proponen la idea de cinco a uno: cinco adultos que se ocupen de cada joven. Tu hijo no necesita cinco papás. Necesita adultos que se ocupen de él."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Aclaran que no se trata de cinco maestros ni de cinco líderes por grupo, ni de subcontratar adultos. La idea es construir un conjunto de relaciones, que puede nacer de un solo grupo unido. Empezar pequeño también cuenta."),
 ("joven", "rewe", "[adolescente, casual, directo] Hay adultos que sí me escuchan. Y no son mis papás."),
 ("papa", "mario", "[papá, pensativo, sincero] Qué bueno que los tiene. Yo también quiero conocerlos."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: escribe los nombres de los adultos que ya conocen y quieren a tu hijo. Y piensa quién podría ser el siguiente. Anota solo los que ya existen. Hoy, solo escribe."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: lo que tu hijo quizá no se atreve a decir."),
], [
 ("titular", "gancho", "invierten", "¿Cuántos adultos invierten en tu hijo?", "Cinco sillas alrededor de una mesa, una ya ocupada; sin rostros"),
 ("titular", "idea", "cinco", "Cinco a uno", "«5:1» en tipografía grande, en morado con subrayado amarillo"),
 ("icono", "giro", "subcontratar", "No es subcontratar", "Tarjeta de «contrato» tachada"),
 ("icono", "giro", "relaciones", "Un conjunto de relaciones", "Red de cinco nodos que se conectan en un círculo"),
 ("reaccion", "joven", "escuchan", "Hay adultos que sí me escuchan", "Burbuja del adolescente"),
 ("reaccion", "papa", "conocerlos", "Yo también quiero conocerlos", "Burbuja de papá"),
 ("accion", "accion", "nombres", "Para hoy: escribe los nombres", "Tarjeta «Para hoy» con libreta y lápiz"),
 ("icono", "accion", "siguiente", "¿Quién podría ser el siguiente?", "Una silla vacía que se ilumina"),
 ("titular", "siguiente", "atreve", "Siguiente: lo que no se atreve a decir", "Globo de diálogo con puntos suspensivos"),
], [GB + ", Powell y Clark: proporción 5:1 (PT86)"])

C(12, 2, "Las dudas calladas", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Tu hijo duda de su fe, y te lo dice?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Powell y Clark estudiaron a jóvenes en su paso de la preparatoria a la universidad, y preguntaron por las dudas que recordaban de esa etapa. Esto fue lo que encontraron."),
 ("cita", "marisol", "[firme, cálido, pausado] «Menos de la mitad de los estudiantes encuestados comparten sus dudas y luchas con los adultos o amigos»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Es decir, que muchas dudas se quedan en silencio. No es que no existan. Es que no se dicen. Y un joven que duda en silencio está más solo de lo que parece."),
 ("joven", "rewe", "[adolescente, bajito, dudoso] A veces me pregunto si todo esto es cierto. Pero no se lo digo a nadie."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: pregúntale a tu hijo, con curiosidad y sin corregirlo, si alguna vez ha tenido dudas sobre lo que creemos. Y escucha. Podrías abrir así."),
 ("accion2", "mario", "[papá, sereno, cálido] Si alguna vez dudas, aquí puedes decirlo."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: una fe que es más que una lista de deberes."),
], [
 ("titular", "gancho", "duda", "¿Duda... y te lo dice?", "Signo de interrogación que se queda a medias"),
 ("icono", "idea", "preparatoria", "De la preparatoria a la universidad", "Dos edificios unidos por un puente"),
 ("cita", "cita", "mitad", "«Menos de la mitad de los estudiantes encuestados comparten sus dudas y luchas con los adultos o amigos»", "Tarjeta de cita: Kara Powell y Chap Clark, Cómo criar jóvenes de fe sólida"),
 ("ilustracion", "giro", "silencio", "Dudas que se quedan en silencio", "Globo de diálogo vacío flotando en una habitación en penumbra"),
 ("reaccion", "joven", "cierto", "A veces me pregunto si todo esto es cierto", "Burbuja del adolescente, tenue"),
 ("accion", "accion", "curiosidad", "Para hoy: pregunta con curiosidad, sin corregir", "Tarjeta «Para hoy» con signo de pregunta suave"),
 ("icono", "accion", "escucha", "Y escucha", "Oreja estilizada con onda de sonido"),
 ("reaccion", "accion2", "dudas", "Si alguna vez dudas, aquí puedes decirlo", "Burbuja de papá, tono sereno"),
 ("titular", "siguiente", "deberes", "Siguiente: más que una lista de deberes", "Lista con casillas que se desvanece"),
], [GB + ", Powell y Clark: «Menos de la mitad de los estudiantes…» (PT59)"])

C(12, 3, "Una fe que confía", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿La fe en tu casa es una lista de deberes?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Los autores observan que, cuando los hijos aprenden a vivir como cristianos, lo típico es que reciban una lista de lo que deben y no deben hacer: ir a la iglesia, leer la Biblia, orar, ofrendar, sacar buenas notas."),
 ("cita", "marisol", "[firme, cálido, pausado] Los autores lo llaman el evangelio de la administración del pecado. Y advierten: «Los chicos no están captando este tipo de evangelio por sí solos, sino que lo están aprendiendo de nosotros»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Frente a eso, dicen que en el centro de una fe sólida hay una fe que confía en Dios, y que entiende la obediencia como respuesta a esa confianza."),
 ("papa", "mario", "[papá, sincero, pausado] Yo confío en Dios, y por eso lo hago. No solo porque toca."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: cuéntale a tu hijo por qué tú confías en Dios, y no solo qué haces por obligación."),
 ("tarjeta", "marisol", TARJ + "Cómo criar jóvenes de fe sólida, de Kara Powell y Chap Clark, de Editorial Vida. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "lista", "¿Una lista de deberes?", "Lista con casillas: iglesia, Biblia, oración, ofrenda, notas"),
 ("icono", "idea", "iglesia", "Ir · Leer · Orar · Ofrendar · Buenas notas", "Cinco casillas que se marcan una por una"),
 ("cita", "cita", "evangelio", "«Los chicos no están captando este tipo de evangelio por sí solos, sino que lo están aprendiendo de nosotros»", "Tarjeta de cita: Kara Powell y Chap Clark, Cómo criar jóvenes de fe sólida"),
 ("titular", "giro", "confía", "En el centro: una fe que confía en Dios", "Círculo con «confianza» al centro; la lista alrededor, más pequeña"),
 ("icono", "giro", "obediencia", "La obediencia, como respuesta", "Flecha que va de «confianza» a «obediencia»"),
 ("reaccion", "papa", "toca", "Yo confío en Dios, y por eso lo hago", "Burbuja de papá"),
 ("accion", "accion", "confías", "Para hoy: cuéntale por qué tú confías en Dios", "Tarjeta «Para hoy»"),
 ("icono", "accion", "obligación", "No solo qué haces por obligación", "Casilla de «deber» que se transforma en corazón"),
 ("tarjeta_libro", "tarjeta", "Vida", "Cómo criar jóvenes de fe sólida · Kara Powell y Chap Clark · Editorial Vida", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [GB + ", Powell y Clark: evangelio de la administración del pecado vs. confiar en Jesús (PT25/PT26); «Los chicos no están captando…»"])
